# In code, wo starts as:
old_wo = 'wo=({token:e,handleLogout:t,activeTab:n,theme:r})=>{'
assert old_wo in code, "old_wo not found in code"

# If ko is missing in base code, define both ko and Ro before wo
if 'ko=({currentPage:e,totalItems:t' not in code:
    new_wo = ko_code + ',' + ro_code + ',' + old_wo
    print("Injected both ko and Ro before wo.")
else:
    new_wo = ro_code + ',' + old_wo
    print("Injected Ro before wo (ko already defined).")

code = code.replace(old_wo, new_wo)

# 7. Currency fixes
rupee = chr(8377)
code = re.sub(r'`Base:[^`]*`,ge\(', lambda m: f'`Base: {rupee}`,ge(', code)
code = re.sub(r'`[^`]*`,(ge|ue)\(', lambda m: f'`{rupee}`,{m.group(1)}(', code)

with open(target_file, 'w', encoding='utf-8') as f:
    f.write(code)

print(f"Successfully generated {target_file} (size: {os.path.getsize(target_file)} bytes)")

EOF_PY

echo "[2/5] Compiling optimized paginated bundle with Customer Retention..."
python3 /tmp/build_bundle.py "${BASE_BUNDLE}" "${TARGET_BUNDLE}"

echo "[3/5] Verifying JavaScript syntax via Node.js..."
if node -c "${TARGET_BUNDLE}"; then
    echo "       JavaScript syntax check: PASSED (0 errors)"
else
    echo "ERROR: JavaScript syntax check FAILED!"
    exit 1
fi

echo "[4/5] Updating cache buster in index.html to ?v=8..."
sed -i 's/index-paginated\.js[^"'\'' ]*/index-paginated.js?v=8/g' "${HTML_FILE}"
